import { useState } from "react";
import { useEffect } from "react";

// ─── Huisstijl tokens — zelfde als bedrijfswagen calculator ─────────────────
const T = {
  groen:      "#2D5A3D",
  groenLicht: "#3d7a54",
  brons:      "#C17A3A",
  bronsLicht: "#d4924f",
  creme:      "#F0EDE4",
  donker:     "#0e1210",
  donkerMid:  "#161d16",
  donkerCard: "#1e2820",
  tekst:      "#b8ccb4",
  tekstZacht: "#607858",
  rand:       "rgba(255,255,255,0.06)",
};

const LOGO = "data:image/png;base64,";
const CONFIGURATOR_URL = "https://duurzaamopwielen.nl/collections/energie-pakketen";
const VOLTAGE_OPTIONS  = [12, 24, 230];

const SYSTEM_LABELS = [
  { max: 500,  label: "Micro systeem",  desc: "Ideaal voor kamperen of kleine installaties" },
  { max: 1500, label: "Klein systeem",  desc: "Geschikt voor een tiny house of caravan" },
  { max: 4000, label: "Medium systeem", desc: "Goed voor een volledig off-grid weekendverblijf" },
  { max: 9999, label: "Groot systeem",  desc: "Volledige off-grid woning of professioneel gebruik" },
];

const VICTRON_MODELS = [
  { va: 500,   continuW: 400,   multiplus: "MultiPlus 500VA",      quattro: null,               desc: "Starlink, verlichting, kleine elektronica",                            tip: "Beschikbaar in 12V / 24V / 48V" },
  { va: 800,   continuW: 650,   multiplus: "MultiPlus 800VA",      quattro: null,               desc: "Kleine camper of boot, laptop, laders, verlichting",                   tip: "Beschikbaar in 12V / 24V / 48V" },
  { va: 1200,  continuW: 1000,  multiplus: "MultiPlus 1200VA",     quattro: null,               desc: "Compacte off-grid setup, kleine koelkast of TV",                       tip: "Beschikbaar in 12V / 24V / 48V" },
  { va: 1600,  continuW: 1300,  multiplus: "MultiPlus 1600VA",     quattro: null,               desc: "Tiny house basis: koelkast, verlichting en elektronica tegelijk",       tip: "Beschikbaar in 12V / 24V / 48V" },
  { va: 2000,  continuW: 1600,  multiplus: "MultiPlus 2000VA",     quattro: null,               desc: "Comfortabele kleine off-grid installatie, meerdere apparaten",          tip: "Beschikbaar in 12V / 24V / 48V" },
  { va: 3000,  continuW: 2400,  multiplus: "MultiPlus-II 3000VA",  quattro: "Quattro 3000VA",   desc: "Populair voor campers, tiny houses en kleine off-grid woningen",         tip: "Generator? Sluit die aan op de AC-ingang van de MultiPlus-II" },
  { va: 4000,  continuW: 3400,  multiplus: "MultiPlus-II 4000VA",  quattro: "Quattro 4000VA",   desc: "Krachtige off-grid setup voor grotere campers en tiny houses",           tip: "Generator? Sluit die aan op de AC-ingang van de MultiPlus-II" },
  { va: 5000,  continuW: 4000,  multiplus: "MultiPlus-II 5000VA",  quattro: "Quattro 5000VA",   desc: "Meest gekozen voor volledige off-grid woningen",                        tip: "Generator? Sluit die aan op de AC-ingang van de MultiPlus-II" },
  { va: 8000,  continuW: 6500,  multiplus: "MultiPlus-II 8000VA",  quattro: "Quattro 8000VA",   desc: "Zwaar gebruik: meerdere grote apparaten langdurig gelijktijdig",        tip: "MultiPlus-II 8000VA is alleen beschikbaar in 48V" },
  { va: 10000, continuW: 8000,  multiplus: "MultiPlus-II 10000VA", quattro: "Quattro 10000VA",  desc: "Grote off-grid installaties en kleine bedrijven",                      tip: "Parallel schakelen mogelijk tot 6 units" },
  { va: 15000, continuW: 12000, multiplus: "MultiPlus-II 15000VA", quattro: "Quattro 15000VA",  desc: "Professioneel en industrieel gebruik",                                 tip: "Neem contact op voor advies bij dit vermogen" },
];

const getVictronModel = w  => VICTRON_MODELS.find(m => m.continuW > w) || VICTRON_MODELS[VICTRON_MODELS.length - 1];
const getSystem       = wh => SYSTEM_LABELS.find(s => wh <= s.max) || SYSTEM_LABELS[3];
const calcWh          = d  => { const h=parseFloat(d.hours)||0,v=parseFloat(d.value)||0,volt=parseFloat(d.voltage)||230; return d.unit==="W"?v*h:v*volt*h; };
const fmtHours        = h  => { const hrs=parseFloat(h)||0; if(hrs<=0)return ""; const totalMin=Math.round(hrs*60); const u=Math.floor(totalMin/60),m=totalMin%60; if(u===0)return `${m} min`; if(m===0)return `${u} uur`; return `${u}u ${m}min`; };
const calcW           = d  => { const v=parseFloat(d.value)||0,volt=parseFloat(d.voltage)||230; return d.unit==="W"?v:v*volt; };
const calcWp          = wh => wh/(4*0.7);
const newDevice       = () => ({ id:Date.now()+Math.random(), name:"", value:"", unit:"W", voltage:230, hours:"" });

// ─── Google Fonts loader ─────────────────────────────────────────────────────
function useManrope() {
  useEffect(() => {
    const link = document.createElement("link");
    link.href = "https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700;800&display=swap";
    link.rel  = "stylesheet";
    document.head.appendChild(link);
  }, []);
}

export default function App() {
  useManrope();

  const [step,       setStep]       = useState(1);
  const [devices,    setDevices]    = useState([newDevice()]);
  const [checkedIds, setCheckedIds] = useState([]);
  const [name,       setName]       = useState("");
  const [email,      setEmail]      = useState("");
  const [submitted,  setSubmitted]  = useState(false);
  const [error,      setError]      = useState("");
  const [showHelp,   setShowHelp]   = useState(false);

  const totalWh  = devices.reduce((s,d)=>s+calcWh(d),0);
  const totalWp  = Math.round(calcWp(totalWh));
  const sys      = getSystem(totalWh);
  const continuW = checkedIds.reduce((s,id)=>{ const d=devices.find(d=>d.id===id); return d?s+calcW(d):s; },0);
  const victron  = getVictronModel(continuW);
  const groter   = VICTRON_MODELS[VICTRON_MODELS.indexOf(victron)+1];

  const addDevice    = ()       => setDevices(p=>[...p,newDevice()]);
  const removeDevice = id       => { setDevices(p=>p.filter(d=>d.id!==id)); setCheckedIds(p=>p.filter(i=>i!==id)); };
  const updateDevice = (id,f,v) => setDevices(p=>p.map(d=>d.id===id?{...d,[f]:v}:d));
  const toggleCheck  = id       => setCheckedIds(p=>p.includes(id)?p.filter(i=>i!==id):[...p,id]);

  const handleCalculate = () => {
    if (devices.some(d=>!d.name||!d.value||!d.hours)) { setError("Vul alle apparaten volledig in."); return; }
    setError(""); setStep(2);
  };
  const handleToInverter = () => {
    setStep(3);
  };
  const handleEmailSubmit = () => {
    if (!name||!email) { setError("Vul je naam en e-mailadres in."); return; }
    setError(""); setSubmitted(true);
  };
  const reset = () => { setStep(1); setDevices([newDevice()]); setCheckedIds([]); setName(""); setEmail(""); setSubmitted(false); setError(""); };

  const font = { fontFamily:"'Manrope', sans-serif" };

  return (
    <div style={{ ...font, minHeight:"100vh", background:"#E4E0D6", color:T.donker }}>
      <style>{`@media (max-width:480px){ .dow-lbl{ display:none; } .dow-row{ flex-wrap:nowrap !important; gap:5px !important; } .dow-row .dow-val{ flex:1 1 0 !important; min-width:0 !important; width:0 !important; padding-left:9px !important; padding-right:9px !important; } .dow-row select{ padding-left:5px !important; padding-right:0 !important; font-size:13px !important; } .dow-row .dow-hours{ width:60px !important; flex:0 0 auto; padding-left:7px !important; padding-right:3px !important; -moz-appearance:textfield; } .dow-row .dow-hours::-webkit-inner-spin-button, .dow-row .dow-hours::-webkit-outer-spin-button{ -webkit-appearance:none; margin:0; } .dow-row .dow-hours::placeholder{ font-size:11px; } .dow-badge{ font-size:12.5px !important; letter-spacing:0 !important; padding-left:10px !important; padding-right:10px !important; } } @media (max-width:359px){ .dow-row{ flex-wrap:wrap !important; } .dow-row .dow-val{ flex:1 1 70px !important; min-width:70px !important; } }`}</style>

      {/* ── Logo bar ── */}
      <div style={{ background:T.creme, borderBottom:`1px solid rgba(45,90,61,0.12)`, padding:"18px 32px", display:"flex", alignItems:"center", justifyContent:"center" }}>
        <img src={LOGO} alt="Duurzaam op Wielen"
          style={{ height:120, width:"auto", maxWidth:"80%", display:"block" }}
          onError={e=>e.target.style.display="none"} />
      </div>

      {/* ── Hero ── */}
      <div style={{ background:T.creme, borderBottom:`3px solid ${T.brons}`, paddingBottom:0 }}>
        <div style={{ maxWidth:860, margin:"0 auto", padding:"32px 24px 0", textAlign:"center" }}>

          <div style={{ fontSize:11, fontWeight:800, letterSpacing:"0.32em", textTransform:"uppercase", color:T.groen, marginBottom:14 }}>
            Off-Grid Energie Calculator
          </div>

          <h1 style={{ fontSize:"clamp(24px,5vw,42px)", fontWeight:800, color:T.groen, lineHeight:1.15, marginBottom:12, letterSpacing:"-0.02em" }}>
            Hoeveel stroom heb jij <em style={{ fontStyle:"normal", color:T.brons }}>nodig?</em>
          </h1>

          <p style={{ fontSize:14, color:`rgba(45,90,61,0.7)`, lineHeight:1.75, maxWidth:560, margin:"0 auto 28px" }}>
            Bereken je dagelijks verbruik, het benodigde zonnepaneelvermogen en de juiste Victron-omvormer voor jouw off-grid installatie.
          </p>

          {/* Stap indicator */}
          <div style={{ display:"flex", justifyContent:"center", alignItems:"center", gap:0, marginBottom:0, flexWrap:"nowrap" }}>
            {["Apparaten","Energie","Omvormer","Rapport"].map((label,i)=>{
              const active=step===i+1, done=step>i+1;
              return (
                <div key={i} style={{ display:"flex", alignItems:"center" }}>
                  <div style={{ display:"flex", flexDirection:"column", alignItems:"center", padding:"10px 6px" }}>
                    <div style={{
                      width:28, height:28, borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center",
                      fontSize:12, fontWeight:800,
                      background: done ? T.brons : active ? T.groen : "transparent",
                      color: done||active ? T.creme : T.tekstZacht,
                      border: done||active ? "none" : `2px solid rgba(45,90,61,0.2)`,
                      marginBottom:5, flexShrink:0,
                    }}>
                      {done?"✓":i+1}
                    </div>
                    <span style={{ fontSize:10, fontWeight:700, letterSpacing:"0.04em", textTransform:"uppercase", color: done||active ? T.groen : T.tekstZacht, whiteSpace:"nowrap" }}>
                      {label}
                    </span>
                  </div>
                  {i<3&&<div style={{ width:20, height:1, background:`rgba(45,90,61,0.15)`, marginBottom:18, flexShrink:0 }}/>}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* ── Main ── */}
      <main style={{ maxWidth:860, margin:"0 auto", padding:"32px 24px" }}>

        {/* ════ STAP 1: Apparaten ════ */}
        {step===1&&(
          <div>
            <div style={card}>
              <div style={sectionLabel}>Stap 1 — Jouw apparaten</div>
              <h2 style={{ ...cardTitle, color:T.groen }}>Welke apparaten gebruik jij?</h2>
              <p style={{ ...cardSub, marginBottom:8 }}>Voeg al je apparaten toe met het verbruik en de dagelijkse gebruiksduur.</p>
              <div style={{ display:"flex", gap:10, alignItems:"flex-start", marginBottom: showHelp?10:20 }}>
                <p style={{ ...cardSub, fontSize:12, margin:0, flex:1, color:"rgba(96,120,88,0.8)" }}>
                  Uren per dag: gebruik de pijltjes (stappen van 15 minuten) of typ zelf een getal, bijvoorbeeld 0,1 voor 6 minuten. In de balk onder het apparaat zie je direct de omgerekende tijd.
                </p>
                <button type="button" onClick={()=>setShowHelp(v=>!v)} aria-label="Hulp bij het invullen" aria-expanded={showHelp}
                  style={{ flexShrink:0, width:24, height:24, borderRadius:"50%", border:`1.5px solid ${T.groen}`, background: showHelp?T.groen:"transparent", color: showHelp?T.creme:T.groen, fontSize:13, fontWeight:800, fontFamily:"'Manrope',sans-serif", lineHeight:1, cursor:"pointer", padding:0, display:"flex", alignItems:"center", justifyContent:"center" }}>
                  i
                </button>
              </div>
              {showHelp&&(
                <div style={{ background:"rgba(45,90,61,0.04)", border:"1px solid rgba(45,90,61,0.12)", borderRadius:2, padding:"16px 18px", marginBottom:20, fontSize:13, lineHeight:1.7, color:T.tekstZacht }}>
                  <p style={{ margin:"0 0 12px" }}>
                    <strong style={{ color:T.groen }}>Watt (W)</strong><br/>
                    Het vermogen van een apparaat staat meestal op het typeplaatje of in de handleiding, bijvoorbeeld 60 W. Kies dan W en voer dat getal in.
                  </p>
                  <p style={{ margin:"0 0 12px" }}>
                    <strong style={{ color:T.groen }}>Alleen ampère (A)?</strong><br/>
                    Staat er alleen een stroomsterkte op, bijvoorbeeld 5 A? Kies dan A, kies de spanning (V) waarop het apparaat werkt (12V, 24V of 230V, zie het typeplaatje) en voer de A-waarde in. De calculator rekent het zelf om naar watt.
                  </p>
                  <p style={{ margin:0 }}>
                    <strong style={{ color:T.groen }}>Uren per dag</strong><br/>
                    Hoe lang het apparaat per dag aan staat, bijvoorbeeld 8 uur. Gebruik de pijltjes (stappen van 15 minuten) of typ zelf een getal: 0,5 is een half uur, 0,25 is 15 minuten en 0,1 is 6 minuten. In de balk onder het apparaat zie je direct de omgerekende tijd.
                  </p>
                </div>
              )}

              <div style={{ display:"flex", flexDirection:"column", gap:12, marginBottom:12 }}>
                {devices.map((d,idx)=>(
                  <div key={d.id} style={{ display:"flex", gap:10, alignItems:"flex-start" }}>
                    <div style={numBadge}>{idx+1}</div>
                    <div style={{ flex:1, minWidth:0, display:"flex", flexDirection:"column", gap:7 }}>
                      <input style={inputStyle} placeholder="Naam apparaat (bijv. Koelkast 12V)"
                        value={d.name} onChange={e=>updateDevice(d.id,"name",e.target.value)}/>
                      <div className="dow-row" style={{ display:"flex", gap:7, flexWrap:"wrap" }}>
                        <input className="dow-val" style={{...inputStyle,flex:1,minWidth:70}} placeholder="Verbruik" type="number"
                          value={d.value} onChange={e=>updateDevice(d.id,"value",e.target.value)}/>
                        <select style={selectStyle} value={d.unit} onChange={e=>updateDevice(d.id,"unit",e.target.value)}>
                          <option>W</option><option>A</option>
                        </select>
                        {d.unit==="A"&&(
                          <select style={selectStyle} value={d.voltage} onChange={e=>updateDevice(d.id,"voltage",e.target.value)}>
                            {VOLTAGE_OPTIONS.map(v=><option key={v} value={v}>{v}V</option>)}
                          </select>
                        )}
                        <input className="dow-hours" style={{...inputStyle,width:95}} placeholder="Uren/dag" type="number"
                            min="0" max="24" step="0.25"
                            value={d.hours} onChange={e=>updateDevice(d.id,"hours",e.target.value)}/>
                      </div>
                      <div className="dow-badge" style={{ ...inputStyle, display:"flex", alignItems:"center", fontWeight:700, letterSpacing:"0.04em",
                        ...(calcWh(d)>0
                          ? { color:T.brons, background:"rgba(45,90,61,0.04)", border:"1.5px solid rgba(45,90,61,0.1)" }
                          : { color:`rgba(96,120,88,0.5)`, background:"rgba(45,90,61,0.04)", border:"1.5px solid rgba(45,90,61,0.1)", fontWeight:500 }) }}>
                        {calcWh(d)>0
                          ? <span>{Math.round(calcWh(d))} Wh/dag · {Math.round(calcW(d))}W{fmtHours(d.hours)?<>{" · "}<span className="dow-lbl">gebruik: </span>{fmtHours(d.hours)}/dag</>:""}</span>
                          : "Wh/dag verschijnt hier"}
                      </div>
                    </div>
                    {devices.length>1&&(
                      <button style={{ background:"none", border:"none", color:T.tekstZacht, cursor:"pointer", fontSize:15, padding:8, marginTop:8 }}
                        onClick={()=>removeDevice(d.id)}>✕</button>
                    )}
                  </div>
                ))}
              </div>

              <button style={addBtnStyle} onClick={addDevice}>+ Apparaat toevoegen</button>

              {totalWh>0&&(
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", background:`rgba(45,90,61,0.06)`, border:`1px solid rgba(45,90,61,0.15)`, borderRadius:2, padding:"12px 16px", marginBottom:14 }}>
                  <span style={{ color:T.tekstZacht, fontSize:14, fontWeight:500 }}>Huidig totaal</span>
                  <span style={{ color:T.groen, fontWeight:800, fontSize:18 }}>{Math.round(totalWh)} Wh/dag</span>
                </div>
              )}

              {error&&<p style={{ color:"#c0392b", fontSize:13, marginBottom:8 }}>{error}</p>}
              <button style={primaryBtn} onClick={handleCalculate}>Bereken mijn systeem →</button>
            </div>
          </div>
        )}

        {/* ════ STAP 2: Energie resultaat ════ */}
        {step===2&&(
          <div>

            {/* Getallen */}
            <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:12, marginBottom:16 }}>
              {[[Math.round(totalWh),"Wh per dag","Dagverbruik"],[totalWp,"Wp benodigd","Zonnepanelen"]].map(([val,unit,note])=>(
                <div key={unit} style={{ background:T.groen, borderRadius:2, textAlign:"center", padding:"20px 12px", boxShadow:"0 2px 8px rgba(45,90,61,0.2)" }}>
                  <div style={{ fontSize:32, fontWeight:800, color:T.creme, letterSpacing:-1, lineHeight:1 }}>{val}</div>
                  <div style={{ fontSize:11, color:"rgba(240,237,228,0.75)", marginTop:6, fontWeight:700, textTransform:"uppercase", letterSpacing:"0.1em" }}>{unit}</div>
                  <div style={{ fontSize:11, color:"rgba(240,237,228,0.5)", marginTop:3 }}>{note}</div>
                </div>
              ))}
            </div>

            {/* Uitleg + Advies */}
            <div style={{ ...card, background:"rgba(45,90,61,0.04)", marginBottom:16 }}>
              <div style={sectionLabel}>Berekening</div>
              <p style={{ color:T.tekstZacht, fontSize:13, margin:"0 0 16px", lineHeight:1.7 }}>
                {Math.round(totalWh)} Wh ÷ (4 zonuren × 70% rendement) = <strong style={{ color:T.groen }}>{totalWp} Wp</strong><br/>
                <span style={{ fontSize:12, color:`rgba(96,120,88,0.7)` }}>Gebaseerd op 4 zonuren/dag (NL gemiddeld) en 70% systeemrendement</span>
              </p>
              {/* Zonnepaneel advies */}
              <div style={{ background:"rgba(193,122,58,0.12)", border:"1px solid rgba(193,122,58,0.3)", borderRadius:2, padding:"14px 16px" }}>
                <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.18em", textTransform:"uppercase", color:T.brons, marginBottom:8 }}>Zonnepaneeladvies</div>
                <p style={{ color:T.tekstZacht, fontSize:13, margin:0, lineHeight:1.75 }}>
                  Om zo lang mogelijk off-grid te blijven adviseren wij minimaal{" "}
                  <strong style={{ color:T.groen, fontSize:15, fontWeight:800 }}>{totalWp.toLocaleString()} Wp</strong>{" "}
                  aan zonnepanelen te installeren om je dagverbruik aan te vullen. Met dit vermogen laad je bij gemiddeld 4 zonuren per dag
                  je volledige dagverbruik weer op, zodat je de volgende dag opnieuw volledig zelfvoorzienend bent.
                  Houd er rekening mee dat bewolkte dagen minder opbrengst geven en je accu dan als buffer dient.
                </p>
              </div>
            </div>

            {/* Accuadvies */}
            <div style={{ ...card, background:"rgba(45,90,61,0.04)", marginBottom:16 }}>
              <div style={sectionLabel}>Accuadvies</div>
              <p style={{ color:T.tekstZacht, fontSize:13, margin:"0 0 18px", lineHeight:1.7 }}>
                Voor een comfortabele off-grid ervaring adviseren wij minimaal 2 dagen accucapaciteit.
                Zo voorkom je een lege accu en verleng je de levensduur van je accu aanzienlijk.
                Onderstaande capaciteiten zijn berekend op basis van 80% bruikbare capaciteit van een lithium accu.
              </p>

              {/* 12,8V blok */}
              <div style={{ marginBottom:12 }}>
                <div style={{ fontSize:11, fontWeight:800, color:T.groen, textTransform:"uppercase", letterSpacing:"0.12em", marginBottom:8, paddingBottom:6, borderBottom:`2px solid ${T.groen}` }}>
                  12,8V systeem
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                  <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.15)`, borderRadius:2, padding:"14px 16px" }}>
                    <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:T.tekstZacht, marginBottom:2 }}>Minimaal</div>
                    <div style={{ fontSize:11, color:T.tekstZacht, marginBottom:8 }}>1 dag verbruik</div>
                    <div style={{ fontSize:28, fontWeight:800, color:T.groen, letterSpacing:-1 }}>{Math.round(totalWh / 0.8 / 12.8)} Ah</div>
                  </div>
                  <div style={{ background:T.groen, borderRadius:2, padding:"14px 16px" }}>
                    <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:"rgba(240,237,228,0.65)", marginBottom:2 }}>Aanbevolen</div>
                    <div style={{ fontSize:11, color:"rgba(240,237,228,0.5)", marginBottom:8 }}>2 dagen verbruik</div>
                    <div style={{ fontSize:28, fontWeight:800, color:T.creme, letterSpacing:-1 }}>{Math.round(totalWh * 2 / 0.8 / 12.8)} Ah</div>
                  </div>
                </div>
              </div>

              {/* 25,6V blok */}
              <div>
                <div style={{ fontSize:11, fontWeight:800, color:T.groen, textTransform:"uppercase", letterSpacing:"0.12em", marginBottom:8, paddingBottom:6, borderBottom:`2px solid ${T.groen}` }}>
                  25,6V systeem
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                  <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.15)`, borderRadius:2, padding:"14px 16px" }}>
                    <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:T.tekstZacht, marginBottom:2 }}>Minimaal</div>
                    <div style={{ fontSize:11, color:T.tekstZacht, marginBottom:8 }}>1 dag verbruik</div>
                    <div style={{ fontSize:28, fontWeight:800, color:T.groen, letterSpacing:-1 }}>{Math.round(totalWh / 0.8 / 25.6)} Ah</div>
                  </div>
                  <div style={{ background:T.groen, borderRadius:2, padding:"14px 16px" }}>
                    <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:"rgba(240,237,228,0.65)", marginBottom:2 }}>Aanbevolen</div>
                    <div style={{ fontSize:11, color:"rgba(240,237,228,0.5)", marginBottom:8 }}>2 dagen verbruik</div>
                    <div style={{ fontSize:28, fontWeight:800, color:T.creme, letterSpacing:-1 }}>{Math.round(totalWh * 2 / 0.8 / 25.6)} Ah</div>
                  </div>
                </div>
              </div>

            </div>

            {/* Apparaten */}
            <div style={{ marginBottom:16, paddingTop:4 }}>
              <div style={{ borderTop:`2px solid ${T.groen}`, paddingTop:14 }}>
                <div style={sectionLabel}>Jouw apparaten</div>
                {devices.map(d=>(
                  <div key={d.id} style={{ display:"flex", justifyContent:"space-between", padding:"7px 0", borderBottom:`1px solid rgba(45,90,61,0.08)` }}>
                    <span style={{ color:T.tekstZacht, fontSize:13 }}>{d.name}</span>
                    <span style={{ color:T.brons, fontWeight:700, fontSize:13 }}>{Math.round(calcWh(d))} Wh</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Omvormer CTA — centraal */}
            <div style={{ background:T.groen, borderRadius:2, padding:"28px 24px", marginBottom:14, textAlign:"center" }}>
              <div style={{ fontWeight:800, color:T.creme, fontSize:16, marginBottom:6 }}>Bereken ook jouw Victron omvormer</div>
              <div style={{ color:`rgba(240,237,228,0.7)`, fontSize:13, marginBottom:18 }}>Selecteer welke apparaten langdurig gelijktijdig aan staan en ontdek welke omvormer je nodig hebt</div>
              <button style={{ background:T.brons, color:T.creme, border:"none", borderRadius:2, padding:"13px 32px", fontSize:15, fontWeight:700, cursor:"pointer", fontFamily:"'Manrope',sans-serif" }}
                onClick={handleToInverter}>
                Omvormer berekenen →
              </button>
            </div>

            <div style={{ textAlign:"center" }}>
              <button style={{ background:"none", border:"none", color:T.tekstZacht, fontSize:13, cursor:"pointer", fontFamily:"'Manrope',sans-serif", textDecoration:"underline" }} onClick={()=>setStep(1)}>
                ← Terug naar apparaten
              </button>
            </div>
          </div>
        )}

        {/* ════ STAP 3: Omvormer ════ */}
        {step===3&&(
          <div>
            <div style={card}>
              <div style={sectionLabel}>Stap 3 — Omvormeradvies</div>
              <h2 style={{ ...cardTitle, color:T.groen }}>Welke apparaten staan <em style={{ fontStyle:"normal", color:T.brons }}>langdurig</em> gelijktijdig aan?</h2>
              <p style={{ color:T.tekstZacht, fontSize:14, margin:"0 0 20px", lineHeight:1.6 }}>
                Vink alle apparaten aan die tegelijk aan kunnen staan en kijk daarbij vooral naar het maximale vermogen. Zo zie je hoeveel de omvormer continue moet kunnen leveren wanneer er het meeste wordt gevraagd. Dat bepaalt welke Victron omvormer je nodig hebt.
              </p>

              {/* Uitleg */}
              <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"13px 16px", marginBottom:20 }}>
                <strong style={{ color:T.groen, fontSize:13 }}>Continue vs. piek vermogen</strong>
                <p style={{ color:T.tekstZacht, fontSize:12, margin:"6px 0 0", lineHeight:1.7 }}>
                  <strong style={{ color:T.groen }}>Continue vermogen</strong> is wat de omvormer langdurig levert, dit bepaalt het model.<br/>
                  <strong style={{ color:T.groen }}>Piek vermogen</strong> (motorstart koelkast e.d.) duurt slechts seconden. Victron heeft dit ruim ingebouwd.
                </p>
              </div>

              {/* Checkboxes */}
              <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:20 }}>
                {devices.map(d=>{
                  const checked=checkedIds.includes(d.id);
                  const watt=Math.round(calcW(d));
                  return (
                    <div key={d.id} onClick={()=>toggleCheck(d.id)}
                      style={{ display:"flex", alignItems:"center", gap:14, padding:"14px 16px", borderRadius:2, cursor:"pointer",
                        background: checked ? `rgba(193,122,58,0.08)` : `rgba(45,90,61,0.03)`,
                        border: checked ? `1px solid rgba(193,122,58,0.4)` : `1px solid rgba(45,90,61,0.12)`,
                        transition:"all 0.15s" }}>
                      <div style={{ width:22, height:22, borderRadius:2, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0,
                        background: checked ? T.brons : "transparent",
                        border: checked ? `2px solid ${T.brons}` : `2px solid rgba(45,90,61,0.25)` }}>
                        {checked&&<span style={{ color:T.creme, fontSize:12, fontWeight:900 }}>✓</span>}
                      </div>
                      <div style={{ flex:1 }}>
                        <div style={{ color: checked ? T.groen : T.tekstZacht, fontWeight: checked?700:400, fontSize:15 }}>{d.name}</div>
                        <div style={{ color:`rgba(96,120,88,0.6)`, fontSize:12, marginTop:2 }}>{d.hours}u/dag · {d.value}{d.unit}{d.unit==="A"?` @ ${d.voltage}V`:""}</div>
                      </div>
                      <div style={{ textAlign:"right" }}>
                        <div style={{ color: checked ? T.brons : T.tekstZacht, fontWeight:800, fontSize:18 }}>{watt}W</div>
                        <div style={{ color:`rgba(96,120,88,0.5)`, fontSize:11, marginTop:2 }}>{checked?"aan":"uit"}</div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Resultaat */}
              <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"20px", marginBottom:20 }}>
                <div style={{ display:"flex", gap:16, flexWrap:"wrap", paddingBottom: continuW>0?18:0, marginBottom: continuW>0?18:0, borderBottom: continuW>0?`1px solid rgba(45,90,61,0.1)`:"none" }}>
                  <div style={{ flex:1, minWidth:130 }}>
                    <div style={{ color:T.tekstZacht, fontSize:12, fontWeight:600, textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:8 }}>Continue vermogen gelijktijdig</div>
                    <div style={{ color:T.brons, fontWeight:800, fontSize:42, letterSpacing:-2, lineHeight:1 }}>
                      {Math.round(continuW)}<span style={{ fontSize:22 }}>W</span>
                    </div>
                    <div style={{ color:T.tekstZacht, fontSize:12, marginTop:8 }}>
                      {checkedIds.length===0?"Selecteer apparaten hierboven":`${checkedIds.length} apparaat${checkedIds.length===1?"":"en"} langdurig aan`}
                    </div>
                  </div>
                  {continuW>0&&(
                    <div style={{ flex:1, minWidth:130, borderLeft:`1px solid rgba(45,90,61,0.12)`, paddingLeft:16 }}>
                      <div style={{ color:T.tekstZacht, fontSize:12, fontWeight:600, textTransform:"uppercase", letterSpacing:"0.08em", marginBottom:8 }}>Continue limiet aanbevolen model</div>
                      <div style={{ color:T.groen, fontWeight:800, fontSize:42, letterSpacing:-2, lineHeight:1 }}>
                        {victron.continuW.toLocaleString()}<span style={{ fontSize:22 }}>W</span>
                      </div>
                      <div style={{ color:T.tekstZacht, fontSize:12, marginTop:8 }}>
                        Ruimte over: <strong style={{ color:T.groen }}>{(victron.continuW-Math.round(continuW)).toLocaleString()}W</strong>
                      </div>
                    </div>
                  )}
                </div>

                {continuW>0&&(
                  <>
                    <div style={{ fontSize:11, fontWeight:700, color:T.tekstZacht, textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:12 }}>Aanbevolen Victron model</div>

                    {/* MultiPlus kaart = ons advies */}
                    <div style={{ background:T.groen, border:`2px solid ${T.groen}`, borderRadius:2, padding:"20px", marginBottom:10, boxShadow:"0 4px 16px rgba(45,90,61,0.25)" }}>
                      <div style={{ display:"inline-block", background:T.brons, color:T.creme, fontSize:10, fontWeight:800, letterSpacing:"0.16em", textTransform:"uppercase", padding:"4px 10px", borderRadius:2, marginBottom:12 }}>
                        Ons advies
                      </div>
                      <div style={{ fontSize:10, fontWeight:800, color:"rgba(240,237,228,0.65)", textTransform:"uppercase", letterSpacing:"0.12em", marginBottom:4 }}>
                        {victron.va<=2000?"MultiPlus":"MultiPlus-II"}
                      </div>
                      <div style={{ color:T.creme, fontWeight:800, fontSize:22, letterSpacing:"-0.01em", marginBottom:12 }}>{victron.multiplus}</div>
                      <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                        <span style={{ background:"rgba(240,237,228,0.15)", color:T.creme, fontSize:13, padding:"5px 12px", borderRadius:2, fontWeight:700 }}>
                          {victron.continuW.toLocaleString()}W continue
                        </span>
                        <span style={{ background:T.brons, color:T.creme, fontSize:13, padding:"5px 12px", borderRadius:2, fontWeight:700 }}>
                          {victron.va.toLocaleString()}VA
                        </span>
                      </div>
                    </div>

                    {/* Ruimer alternatief */}
                    {groter&&(
                      <div style={{ background:T.creme, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"16px", marginBottom:12 }}>
                        <div style={{ fontSize:10, fontWeight:800, color:T.tekstZacht, textTransform:"uppercase", letterSpacing:"0.12em", marginBottom:8 }}>Ruimer alternatief</div>
                        <div style={{ color:T.groen, fontWeight:800, fontSize:16, marginBottom:10 }}>{groter.multiplus}</div>
                        <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
                          <span style={{ background:`rgba(45,90,61,0.1)`, color:T.groen, fontSize:12, padding:"4px 10px", borderRadius:2, fontWeight:700 }}>
                            {groter.continuW.toLocaleString()}W continue
                          </span>
                          <span style={{ background:`rgba(193,122,58,0.1)`, color:T.brons, fontSize:12, padding:"4px 10px", borderRadius:2, fontWeight:600 }}>
                            {groter.va.toLocaleString()}VA
                          </span>
                          <span style={{ background:`rgba(45,90,61,0.06)`, color:T.tekstZacht, fontSize:12, padding:"4px 10px", borderRadius:2, fontWeight:600 }}>
                            {(groter.continuW-Math.round(continuW)).toLocaleString()}W ruimte over
                          </span>
                        </div>
                        <div style={{ color:T.tekstZacht, fontSize:12, marginTop:10, lineHeight:1.6 }}>Meer marge voor later uitbreiden of apparaten die je nu nog niet meetelt.</div>
                      </div>
                    )}

                    <div style={{ background:`rgba(193,122,58,0.06)`, border:`1px solid rgba(193,122,58,0.15)`, borderRadius:2, padding:"12px 14px" }}>
                      <div style={{ color:T.tekstZacht, fontSize:13, marginBottom:4 }}>{victron.desc}</div>
                      <div style={{ color:`rgba(96,120,88,0.7)`, fontSize:12, fontStyle:"italic" }}>{victron.tip}</div>
                      <div style={{ color:`rgba(96,120,88,0.7)`, fontSize:12, marginTop:8, lineHeight:1.6 }}>
                        Gebruik je af en toe een generator op de ingang als backup? Dan is een MultiPlus voldoende. Staat er een permanente generator naast, wat vaak voorkomt bij boten? Dan adviseren we een Quattro, omdat deze 2 AC-ingangen heeft.
                      </div>
                    </div>
                  </>
                )}
              </div>

              <div style={{ display:"flex", gap:10 }}>
                <button style={secondaryBtn} onClick={()=>setStep(2)}>← Energie resultaat</button>
                <button style={primaryBtn} onClick={()=>setStep(4)}>Volledige rapportage ontvangen</button>
              </div>
            </div>
          </div>
        )}

        {/* ════ STAP 4: E-mail ════ */}
        {step===4&&!submitted&&(
          <div style={card}>
            <div style={sectionLabel}>Stap 4 — Jouw rapport</div>
            <h2 style={{ ...cardTitle, color:T.groen }}>Ontvang jouw persoonlijke rapport</h2>
            <p style={{ color:T.tekstZacht, fontSize:14, margin:"0 0 22px", lineHeight:1.6 }}>
              We sturen je een compleet overzicht van je energieverbruik en omvormeradvies gratis per mail.
            </p>

            {/* Preview */}
            <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"16px 18px", marginBottom:22, display:"flex", flexDirection:"column", gap:10 }}>
              {[
                [null,"Volledig overzicht van al je apparaten"],
                [null,`${Math.round(totalWh)} Wh/dag · ${totalWp} Wp`],
                ...(continuW>0?[[null,`${Math.round(continuW)}W continue · ${victron.multiplus}`]]:[] ),
                [null,`Minimaal ${Math.round(totalWh / 0.8 / 12.8)} Ah (12,8V) · Aanbevolen ${Math.round(totalWh * 2 / 0.8 / 12.8)} Ah`],
                [null,`Minimaal ${Math.round(totalWh / 0.8 / 25.6)} Ah (25,6V) · Aanbevolen ${Math.round(totalWh * 2 / 0.8 / 25.6)} Ah`],
                [null,"Directe link naar de pakketconfigurator"],
              ].map(([,text])=>(
                <div key={text} style={{ display:"flex", gap:10, alignItems:"center", color:T.tekstZacht, fontSize:14 }}>
                  <span style={{ width:6, height:6, borderRadius:"50%", background:T.brons, flexShrink:0 }}/><span>{text}</span>
                </div>
              ))}
            </div>

            {/* Mini samenvatting */}
            <div style={{ display:"flex", gap:10, marginBottom:22, flexWrap:"wrap" }}>
              {[[Math.round(totalWh),"Wh/dag"],[totalWp,"Wp"],...(continuW>0?[[Math.round(continuW)+"W","continue"]]:[])]
                .map(([v,l])=>(
                  <div key={l} style={{ flex:1, minWidth:70, background:T.creme, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"14px 10px", textAlign:"center" }}>
                    <div style={{ color:T.brons, fontWeight:800, fontSize:22 }}>{v}</div>
                    <div style={{ color:T.tekstZacht, fontSize:11, marginTop:4, textTransform:"uppercase", letterSpacing:"0.08em", fontWeight:600 }}>{l}</div>
                  </div>
                ))}
            </div>

            {/* Accu samenvatting */}
            <div style={{ marginBottom:22 }}>
              <div style={{ fontSize:10, fontWeight:800, letterSpacing:"0.18em", textTransform:"uppercase", color:T.brons, marginBottom:10 }}>Accuadvies</div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
                <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"12px 14px" }}>
                  <div style={{ fontSize:10, fontWeight:700, color:T.tekstZacht, textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:2 }}>12,8V Minimaal</div>
                  <div style={{ fontSize:11, color:T.tekstZacht, marginBottom:6 }}>1 dag verbruik</div>
                  <div style={{ fontSize:22, fontWeight:800, color:T.groen }}>{Math.round(totalWh / 0.8 / 12.8)} Ah</div>
                </div>
                <div style={{ background:T.groen, borderRadius:2, padding:"12px 14px" }}>
                  <div style={{ fontSize:10, fontWeight:700, color:"rgba(240,237,228,0.65)", textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:2 }}>12,8V Aanbevolen</div>
                  <div style={{ fontSize:11, color:"rgba(240,237,228,0.5)", marginBottom:6 }}>2 dagen verbruik</div>
                  <div style={{ fontSize:22, fontWeight:800, color:T.creme }}>{Math.round(totalWh * 2 / 0.8 / 12.8)} Ah</div>
                </div>
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"12px 14px" }}>
                  <div style={{ fontSize:10, fontWeight:700, color:T.tekstZacht, textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:2 }}>25,6V Minimaal</div>
                  <div style={{ fontSize:11, color:T.tekstZacht, marginBottom:6 }}>1 dag verbruik</div>
                  <div style={{ fontSize:22, fontWeight:800, color:T.groen }}>{Math.round(totalWh / 0.8 / 25.6)} Ah</div>
                </div>
                <div style={{ background:T.groen, borderRadius:2, padding:"12px 14px" }}>
                  <div style={{ fontSize:10, fontWeight:700, color:"rgba(240,237,228,0.65)", textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:2 }}>25,6V Aanbevolen</div>
                  <div style={{ fontSize:11, color:"rgba(240,237,228,0.5)", marginBottom:6 }}>2 dagen verbruik</div>
                  <div style={{ fontSize:22, fontWeight:800, color:T.creme }}>{Math.round(totalWh * 2 / 0.8 / 25.6)} Ah</div>
                </div>
              </div>
            </div>

            <div style={{ marginBottom:14 }}>
              <label style={{ display:"block", color:T.groen, fontSize:13, fontWeight:600, marginBottom:6 }}>Jouw naam</label>
              <input style={inputStyle} placeholder="Jan de Vries" value={name} onChange={e=>setName(e.target.value)}/>
            </div>
            <div style={{ marginBottom:14 }}>
              <label style={{ display:"block", color:T.groen, fontSize:13, fontWeight:600, marginBottom:6 }}>E-mailadres</label>
              <input style={inputStyle} type="email" placeholder="jan@voorbeeld.nl" value={email} onChange={e=>setEmail(e.target.value)}/>
            </div>

            <p style={{ color:`rgba(96,120,88,0.6)`, fontSize:12, marginBottom:18 }}>Je ontvangt je rapport en een follow-up met advies. Daarnaast voeg je jezelf toe aan onze mailinglijst, zodat we je op de hoogte houden van nieuws, tips en aanbiedingen. Afmelden kan op elk moment.</p>

            {error&&<p style={{ color:"#c0392b", fontSize:13, marginBottom:8 }}>{error}</p>}

            <div style={{ display:"flex", gap:10 }}>
              <button style={secondaryBtn} onClick={()=>setStep(continuW>0?3:2)}>← Terug</button>
              <button style={primaryBtn} onClick={handleEmailSubmit}>Stuur mij het rapport →</button>
            </div>
          </div>
        )}

        {/* ════ Bevestiging ════ */}
        {step===4&&submitted&&(
          <div style={{ ...card, textAlign:"center" }}>
            <div style={{ width:40, height:3, background:T.brons, margin:"0 auto 18px" }}/>
            <div style={sectionLabel}>Verstuurd!</div>
            <h2 style={{ ...cardTitle, color:T.groen }}>Rapport onderweg!</h2>
            <p style={{ color:T.tekstZacht, fontSize:14, lineHeight:1.7, marginBottom:24 }}>
              Je rapport is verstuurd naar <strong style={{ color:T.groen }}>{email}</strong>.
            </p>

            <div style={{ background:`rgba(45,90,61,0.05)`, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:20, marginBottom:20, textAlign:"left" }}>
              <div style={{ fontSize:11, fontWeight:700, color:T.tekstZacht, textTransform:"uppercase", letterSpacing:"0.1em", marginBottom:14 }}>Jouw resultaten</div>
              <div style={{ display:"flex", gap:10, flexWrap:"wrap", marginBottom:14 }}>
                {[[Math.round(totalWh),"Wh/dag"],[totalWp,"Wp"],...(continuW>0?[[Math.round(continuW)+"W","continue"],[victron.va+"VA","Victron"]]:[])]
                  .map(([v,l])=>(
                    <div key={l} style={{ background:T.creme, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"12px 14px", textAlign:"center", flex:1, minWidth:70 }}>
                      <div style={{ color:T.brons, fontWeight:800, fontSize:18 }}>{v}</div>
                      <div style={{ color:T.tekstZacht, fontSize:11, marginTop:3, textTransform:"uppercase", letterSpacing:"0.06em" }}>{l}</div>
                    </div>
                  ))}
              </div>
              <p style={{ color:T.tekstZacht, fontSize:13, lineHeight:1.7, margin:0 }}>
                In de mail vind je een link naar de <strong style={{ color:T.groen }}>pakketconfigurator</strong> waar je een compleet systeem samenstelt.
              </p>
            </div>

            {/* Configurator CTA */}
            <div style={{ background:T.groen, borderRadius:2, padding:"22px 24px", marginBottom:14, display:"flex", alignItems:"center", justifyContent:"space-between", gap:16, flexWrap:"wrap" }}>
              <div style={{ flex:1, textAlign:"left" }}>
                <div style={{ fontWeight:800, color:T.creme, fontSize:15, marginBottom:4 }}>Klaar voor een compleet systeem?</div>
                <div style={{ color:`rgba(240,237,228,0.7)`, fontSize:13 }}>Ga direct naar de pakketconfigurator.</div>
              </div>
              <a href={CONFIGURATOR_URL} target="_blank" rel="noopener noreferrer"
                style={{ background:T.brons, color:T.creme, border:"none", borderRadius:2, padding:"12px 22px", fontSize:14, fontWeight:700, cursor:"pointer", textDecoration:"none", whiteSpace:"nowrap", fontFamily:"'Manrope',sans-serif" }}>
                Naar configurator →
              </a>
            </div>

            <button style={secondaryBtn} onClick={reset}>Nieuwe berekening starten</button>
          </div>
        )}

      </main>

      {/* ── Footer ── */}
      <div style={{ borderTop:`3px solid ${T.brons}`, background:T.creme, padding:"24px", textAlign:"center" }}>
        <img src={LOGO} alt="Duurzaam op Wielen" style={{ height:55, width:"auto", maxWidth:"80%", display:"block", margin:"0 auto" }} />
        <p style={{ color:T.tekstZacht, fontSize:12, marginTop:10 }}>© 2026 Duurzaam op Wielen · Energie zonder grenzen</p>
      </div>

    </div>
  );
}

// ─── Gedeelde stijlen ────────────────────────────────────────────────────────
const card        = { background:T.creme, border:`1px solid rgba(45,90,61,0.12)`, borderRadius:2, padding:"28px 24px", boxShadow:"0 2px 12px rgba(45,90,61,0.06)", marginBottom:16 };
const cardTitle   = { fontSize:22, fontWeight:800, margin:"0 0 8px", letterSpacing:"-0.02em" };
const cardSub     = { color:T.tekstZacht, fontSize:14, margin:"0 0 22px", lineHeight:1.6 };
const sectionLabel= { fontSize:10, fontWeight:800, letterSpacing:"0.2em", textTransform:"uppercase", color:T.brons, marginBottom:8, display:"block" };
const numBadge    = { width:28, height:28, borderRadius:"50%", background:`rgba(45,90,61,0.1)`, color:T.groen, display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:800, flexShrink:0, marginTop:10 };
const inputStyle  = { background:"#fff", border:`1.5px solid rgba(45,90,61,0.18)`, borderRadius:2, padding:"10px 13px", color:T.donker, fontSize:14, outline:"none", width:"100%", boxSizing:"border-box", height:42, fontFamily:"'Manrope',sans-serif" };
const selectStyle = { background:"#fff", border:`1.5px solid rgba(45,90,61,0.18)`, borderRadius:2, padding:"10px 11px", color:T.donker, fontSize:14, outline:"none", cursor:"pointer", height:42, boxSizing:"border-box", fontFamily:"'Manrope',sans-serif" };
